# المرحلة 4 «المخترعون» · M4-U2 البرهان والمثلث (المرجع: reference/03_المناهج_والوحدات/M4_U2_البرهان_والمثلث.md، نسخة 1.2)
# يكتب: content/m4/u2/unit.json ودروسها الخمسة (أربعة دروس المرجع، وبوابة الحيّ «محكمة البرهان» باختبار 12)، وجمل gen.pf.* والتسميات ووسوم الأخطاء.
# البراهين بصورها (v): الشكل والحروف تتغيّر، فبند الإتقان والمراجعة والاختبار مسألة جديدة لا صورةُ ما رُئي (D240).
import sys, os, json; sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', 'm2gen'))
from common import *
U=ROOT+'/content/m4/u2'
os.makedirs(U, exist_ok=True)
def tw(a,b): a=dict(a); a['twin']=b; return a
def reason(q,pic,ids): return {"t":"reason","q":q,"pic":pic,"opts":[{"id":ids[0],"ok":True},{"id":ids[1]},{"id":ids[2]}]}
def two(q,ids,hint=None):
    d={"t":"twoReasons","q":q,"opts":[{"id":ids[0],"ok":True},{"id":ids[1],"ok":True},{"id":ids[2]}]}
    if hint: d['hint']=hint
    return d
MAT=lambda: {"prompt":"mat.01","show":[],"icon":True,"after":"mat.02","facts":[]}
BAG=lambda a,b,la,lb: {"items":[{"icon":a,"label":la},{"icon":b,"label":lb}],"ask":"bag.ask"}
RS={'tri':['draw','alt','line'],'vert':['line','line','same'],'alt':['corr','vert','trans'],'coint':['corr','line','swap'],'ineq':['path','short','so'],'poly':['diag','convex','tri']}
def pfp(**o): return {"kind":"pfpic",**o}
def chain(pf,v=0,q=None): d={"t":"prChain","pf":pf,"q":q or "gen.pf.q.chain"}; d.update({"v":v} if v else {}); return d
def why(pf,step,opts,v=0,q=None):
    assert opts[0]==RS[pf][step] and len(set(opts))==3 and all(o not in (RS[pf][step],) for o in opts[1:]), (pf,step,opts)
    d={"t":"prReason","pf":pf,"step":step,"cands":opts,"q":q or "gen.pf.q.reason"}; d.update({"v":v} if v else {}); return d
def tm(a,b): assert a+b<180; return {"t":"triMissing","a":a,"b":b}
def vert(th,g,a): return {"t":"arVert","th":th,"given":g,"ask":a,"q":"gen.ar.q.ang"}
def trc(phi,g,a): return {"t":"arTrCalc","phi":phi,"given":g,"ask":a,"q":"gen.ar.q.ang"}
def yn(*s): return {"t":"ineqYN","s":list(s),"q":"gen.pf.q.ineq"}
def rng(a,b,ask): return {"t":"ineqRange","a":a,"b":b,"ask":ask,"q":"gen.pf.q.range."+ask}
def ipick(*sets):
    ok=[s for s in sets if sorted(s)[0]+sorted(s)[1]>sorted(s)[2]]; assert len(ok)==1, sets
    return {"t":"ineqPick","sets":[list(x) for x in sets],"q":"gen.pf.q.pick"}
def ptri(n): return {"t":"polyTri","n":n,"q":"gen.pf.q.polyTri"}
def psum(n): return {"t":"polySum","n":n,"q":"gen.pf.q.polySum"}
def preg(n,ask): assert 360%n==0 and n!=4; return {"t":"polyReg","n":n,"ask":ask,"q":"gen.pf.q.reg."+ask}
def trap(a,ask): assert a%5==0 and 40<=a<=80; return {"t":"isoTrap","a":a,"ask":ask,"q":"gen.pf.q.trap."+ask}
def build(s,start=4): return {"t":"polyBuild","sum":s,"start":start,"q":"gen.pf.q.build"}
dump(U+'/unit.json', {"id":"m4.u2","title":"البُرْهَانُ وَالمُثَلَّثُ","sub":"المَرْحَلَةُ الرَّابِعَةُ: المُخْتَرِعُونَ","district":"حَيُّ البُرْهَانِ","hosts":["triangle","square","rect"],"hunt":[]})

