L3={
 "bag.ask":"هَلْ {مَعَكَ|مَعَكِ} شَرَائِطُ وَرَقٍ وَمِسْطَرَةٌ؟ أَمْ نَعْمَلُ عَلَى الشَّاشَةِ؟",
 "hk.01":["chaos","هَذِهِ الأَعْوَادُ: اثْنَانِ وَثَلَاثَةٌ وَثَمَانِيَةٌ. هِيَ مُثَلَّثٌ!"],
 "hk.02":"نُدِيرُ العُودَيْنِ القَصِيرَيْنِ حَوْلَ طَرَفَيِ الطَّوِيلِ: لَا يَلْتَقِيَانِ أَبَدًا. فَلَا مُثَلَّثَ.",
 "is.01":"أَرْبَعَةٌ وَخَمْسَةٌ وَسِتَّةٌ: يَلْتَقِي العُودَانِ، فَيُصْنَعُ مُثَلَّثٌ.",
 "is.02":"وَاثْنَانِ وَثَلَاثَةٌ وَخَمْسَةٌ: يَلْتَقِيَانِ عَلَى العُودِ الطَّوِيلِ نَفْسِهِ، فَيَصِيرَانِ خَطًّا مُسْتَقِيمًا وَلَا مُثَلَّثَ.",
 "is.03":"القَاعِدَةُ: فِي كُلِّ مُثَلَّثٍ، مَجْمُوعُ أَيِّ ضِلْعَيْنِ أَكْبَرُ مِنَ الضِّلْعِ الثَّالِثِ.",
 "ip.00":"وَلِمَاذَا؟ مُعْطًى: مُثَلَّثٌ أ ب ج. المَطْلُوبُ: أ ب وَب ج مَعًا أَطْوَلُ مِنْ أ ج.",
 "ip.01":"مِنْ أ إِلَى ب ثُمَّ إِلَى ج طَرِيقٌ يَمُرُّ بِـ ب، وَب لَيْسَتْ عَلَى القِطْعَةِ أ ج.",
 "ip.02":"وَالقِطْعَةُ المُسْتَقِيمَةُ أَقْصَرُ طَرِيقٍ بَيْنَ نُقْطَتَيْنِ.",
 "ip.03":"إِذَنْ أ ب وَب ج مَعًا أَطْوَلُ مِنْ أ ج. وَمِنْ كُلِّ رَأْسٍ مِثْلُ ذَلِكَ.",
 "mat.01":"{قُصَّ|قُصِّي} شَرَائِطَ وَرَقٍ بِأَطْوَالٍ مُخْتَلِفَةٍ، {وَقِسْهَا|وَقِيسِيهَا} بِالمِسْطَرَةِ، {وَجَرِّبْ|وَجَرِّبِي} أَيَّهَا يَصْنَعُ مُثَلَّثًا. ثُمَّ {اِلْمِسْ|اِلْمِسِي} «تَمَّ».",
 "mat.02":"وَالآنَ عَلَى الشَّاشَةِ.",
 "gm.intro":"لُعْبَةُ: القِطَعُ الذَّكِيَّةُ! {اِخْتَرِ|اِخْتَارِي} الأَعْوَادَ الَّتِي تَصْنَعُ مُثَلَّثًا.",
 "pr.intro":"نَتَدَرَّبُ.",
 "pr.r1":"قَالَتْ فَوْضَى: ضِلْعَانِ خَمْسَةٌ وَخَمْسَةٌ يَصْنَعَانِ مَعَ أَيِّ ضِلْعٍ ثَالِثٍ مُثَلَّثًا. مَا خَطَؤُهَا؟",
 "pr.r1a":"الثَّالِثُ يَجِبُ أَنْ يَكُونَ أَقَلَّ مِنْ عَشَرَةٍ.",
 "pr.r1b":"لَا خَطَأَ: الضِّلْعَانِ المُتَسَاوِيَانِ يَكْفِيَانِ.",
 "pr.r1c":"الثَّالِثُ يَجِبُ أَنْ يُسَاوِيَ خَمْسَةً أَيْضًا.",
 "ch.find":"قَالَتْ فَوْضَى: هَذِهِ الأَعْوَادُ الثَّلَاثَةُ تَصْنَعُ مُثَلَّثًا. هَلْ تَصْنَعُ حَقًّا؟",
 "ch.after":["chaos","آه! {أَتَحَقَّقُ|أَتَحَقَّقُ} مِنَ القَصِيرَيْنِ مَعَ الطَّوِيلِ."],
 "ch.right":"القَصِيرَانِ مَعًا أَقْصَرُ مِنَ الطَّوِيلِ.",
 "ch.wrong":["chaos","ثَلَاثَةُ أَعْوَادٍ تَصْنَعُ مُثَلَّثًا دَائِمًا."],
 "ms.1":"لِمَاذَا مَجْمُوعُ ضِلْعَيْنِ فِي المُثَلَّثِ أَكْبَرُ مِنَ الثَّالِثِ؟",
 "ms.1a":"لِأَنَّ الضِّلْعَ الثَّالِثَ قِطْعَةٌ، وَهِيَ أَقْصَرُ طَرِيقٍ بَيْنَ طَرَفَيْهَا.",
 "ms.1b":"لِأَنَّ الضِّلْعَ الثَّالِثَ أَقْصَرُ الأَضْلَاعِ الثَّلَاثَةِ فِي كُلِّ مُثَلَّثٍ.",
 "ms.1c":"لِأَنَّ زَوَايَا المُثَلَّثِ مَجْمُوعُهَا مِئَةٌ وَثَمَانُونَ.",
 "ms.x1":"نَمْلَةٌ عَلَى رَأْسٍ مِنْ مُثَلَّثٍ تُرِيدُ رَأْسًا آخَرَ. لِمَاذَا طَرِيقُهَا عَلَى ضِلْعٍ وَاحِدٍ أَقْصَرُ مِنْ طَرِيقِهَا عَلَى ضِلْعَيْنِ؟",
 "ms.x1a":"لِأَنَّ القِطْعَةَ المُسْتَقِيمَةَ أَقْصَرُ طَرِيقٍ بَيْنَ نُقْطَتَيْنِ.",
 "ms.x1b":"لِأَنَّ الضِّلْعَ الوَاحِدَ أَقْصَرُ أَضْلَاعِ المُثَلَّثِ الثَّلَاثَةِ.",
 "ms.x1c":"لِأَنَّ زَاوِيَةَ الرَّأْسِ الثَّالِثِ قَائِمَةٌ، فَيَطُولُ الطَّرِيقُ حَوْلَهَا.",
 "ms.recall":"نَتَذَكَّرُ: نَجْمَعُ الضِّلْعَيْنِ القَصِيرَيْنِ، فَإِنْ كَانَ المَجْمُوعُ أَكْبَرَ مِنَ الطَّوِيلِ صُنِعَ مُثَلَّثٌ.",
 "ms.ok":"{أَتْقَنْتَ|أَتْقَنْتِ} مُتَبَايِنَةَ المُثَلَّثِ!",
 "wrap.01":"القِطْعَةُ أَقْصَرُ طَرِيقٍ، فَضِلْعَانِ مَعًا أَطْوَلُ مِنَ الثَّالِثِ!",
 "wrap.home":["chaos","مُهِمَّةُ البَيْتِ: {قِسْ|قِيسِي} بِشَرِيطِ القِيَاسِ المَسَافَاتِ بَيْنَ البَابِ وَالسَّرِيرِ وَالنَّافِذَةِ مَعَ {أَهْلِكَ|أَهْلِكِ}، {وَتَحَقَّقْ|وَتَحَقَّقِي} أَنَّ كُلَّ مَسَافَتَيْنِ أَطْوَلُ مِنَ الثَّالِثَةِ، {وَاحْسُبْ|وَاحْسُبِي} كَمْ يَزِيدُ الطَّرِيقُ المَارُّ بِالسَّرِيرِ."],
}
