# ---------------- د4: مجموع زوايا المضلع (C411) وإتقان شبه المنحرف متساوي الساقين (C178) ----------------
L4={
 "bag.ask":"هَلْ {مَعَكَ|مَعَكِ} مِسْطَرَةٌ وَمِنْقَلَةٌ؟ أَمْ نَعْمَلُ عَلَى الشَّاشَةِ؟",
 "hk.01":["chaos","مَجْمُوعُ زَوَايَا الخُمَاسِيِّ ثَلَاثُمِئَةٍ وَسِتُّونَ، مِثْلُ الرُّبَاعِيِّ!"],
 "hk.02":"المُثَلَّثُ هُوَ الأَسَاسُ: نَقْسِمُ الخُمَاسِيَّ بِأَقْطَارٍ مِنْ رَأْسٍ وَاحِدٍ، فَيَصِيرُ ثَلَاثَةَ مُثَلَّثَاتٍ.",
 "hk.03":"وَزَوَايَا المُثَلَّثَاتِ الثَّلَاثَةِ هِيَ زَوَايَا الخُمَاسِيِّ: ثَلَاثَةٌ فِي مِئَةٍ وَثَمَانِينَ، خَمْسُمِئَةٍ وَأَرْبَعُونَ.",
 "pt.01":"المُثَلَّثُ مُثَلَّثٌ وَاحِدٌ، وَالرُّبَاعِيُّ اثْنَانِ، وَالخُمَاسِيُّ ثَلَاثَةٌ، وَالسُّدَاسِيُّ أَرْبَعَةٌ: عَدَدُ الأَضْلَاعِ نَاقِصَ اثْنَيْنِ، لِأَنَّ الرَّأْسَيْنِ المُجَاوِرَيْنِ لَا قُطْرَ إِلَيْهِمَا.",
 "pt.02":"فَمَجْمُوعُ زَوَايَا المُضَلَّعِ المُحَدَّبِ: عَدَدُ أَضْلَاعِهِ نَاقِصَ اثْنَيْنِ، فِي مِئَةٍ وَثَمَانِينَ.",
 "rx.01":"فِي السُّدَاسِيِّ المُنْتَظَمِ زَوَايَاهُ مُتَسَاوِيَةٌ: سَبْعُمِئَةٍ وَعِشْرُونَ عَلَى سِتٍّ، مِئَةٌ وَعِشْرُونَ لِكُلِّ زَاوِيَةٍ.",
 "rx.02":"وَحِينَ نَمُدُّ الضِّلْعَ تَظْهَرُ مُكَمِّلَتُهَا سِتُّونَ، وَهِيَ ثَلَاثُمِئَةٍ وَسِتُّونَ عَلَى سِتٍّ.",
 "tp.01":"شِبْهُ المُنْحَرِفِ المُتَسَاوِي السَّاقَيْنِ لَهُ مِحْوَرُ تَمَاثُلٍ يَقْسِمُهُ نِصْفَيْنِ مُتَطَابِقَيْنِ.",
 "tp.02":"فَزَاوِيَتَا القَاعِدَةِ السُّفْلَى مُتَسَاوِيَتَانِ، لِأَنَّ المِحْوَرَ يُطَابِقُ إِحْدَاهُمَا عَلَى الأُخْرَى.",
 "tp.03":"وَزَاوِيَتَا القَاعِدَةِ العُلْيَا مُتَسَاوِيَتَانِ، وَكُلُّ زَاوِيَةٍ عُلْيَا تُكَمِّلُ السُّفْلَى عَلَى سَاقِهَا، لِأَنَّ القَاعِدَتَيْنِ مُتَوَازِيَتَانِ.",
 "mat.01":"{اُرْسُمْ|اُرْسُمِي} بِالمِسْطَرَةِ مُضَلَّعًا مُحَدَّبًا، {وَقَسِّمْهُ|وَقَسِّمِيهِ} بِأَقْطَارٍ مِنْ رَأْسٍ وَاحِدٍ، {وَقِسْ|وَقِيسِي} زَوَايَاهُ بِالمِنْقَلَةِ {وَاجْمَعْهَا|وَاجْمَعِيهَا}. ثُمَّ {اِلْمِسْ|اِلْمِسِي} «تَمَّ».",
 "mat.02":"وَالآنَ عَلَى الشَّاشَةِ.",
 "gm.intro":"لُعْبَةُ: بِنَاءُ المُضَلَّعَاتِ! {غَيِّرْ|غَيِّرِي} عَدَدَ الأَضْلَاعِ بِالزِّرَّيْنِ.",
 "pr.intro":"نَتَدَرَّبُ.",
 "pr.r1":"قَالَتْ فَوْضَى: مَجْمُوعُ زَوَايَا كُلِّ مُضَلَّعٍ ثَلَاثُمِئَةٍ وَسِتُّونَ. مَا خَطَؤُهَا؟",
 "pr.r1a":"يَزِيدُ مِئَةً وَثَمَانِينَ مَعَ كُلِّ ضِلْعٍ جَدِيدٍ.",
 "pr.r1b":"لَا خَطَأَ: كُلُّ مُضَلَّعٍ تَمْلَأُ زَوَايَاهُ دَوْرَةً كَامِلَةً.",
 "pr.r1c":"المَجْمُوعُ مِئَةٌ وَثَمَانُونَ فِي كُلِّ مُضَلَّعٍ مَهْمَا كَانَ.",
 "ch.find":"قَالَتْ فَوْضَى: مَجْمُوعُ زَوَايَا السُّدَاسِيِّ ثَلَاثُمِئَةٍ وَسِتُّونَ. كَمْ هُوَ حَقًّا؟",
 "ch.after":["chaos","آه! أَعُدُّ المُثَلَّثَاتِ أَوَّلًا."],
 "ch.right":"أَرْبَعَةُ مُثَلَّثَاتٍ فِي مِئَةٍ وَثَمَانِينَ.",
 "ch.wrong":["chaos","كُلُّ مُضَلَّعٍ مِثْلُ الرُّبَاعِيِّ."],
 "ms.1":"قَالَتْ فَوْضَى: فِي مُضَلَّعٍ لَهُ تِسْعَةُ أَضْلَاعٍ تِسْعَةُ مُثَلَّثَاتٍ مِنْ رَأْسٍ وَاحِدٍ. مَا الصَّحِيحُ؟",
 "ms.1a":"سَبْعَةٌ: مِنَ الرَّأْسِ سِتَّةُ أَقْطَارٍ، فَيَنْقَسِمُ إِلَى سَبْعَةِ مُثَلَّثَاتٍ.",
 "ms.1b":"تِسْعَةٌ: لِكُلِّ ضِلْعٍ مِنْ أَضْلَاعِهِ التِّسْعَةِ مُثَلَّثٌ وَاحِدٌ.",
 "ms.1c":"ثَمَانِيَةٌ: لِكُلِّ رَأْسٍ غَيْرِ رَأْسِ البَدْءِ مُثَلَّثٌ وَاحِدٌ.",
 "ms.2":"لِمَاذَا تَتَسَاوَى زَاوِيَتَا القَاعِدَةِ فِي شِبْهِ المُنْحَرِفِ المُتَسَاوِي السَّاقَيْنِ؟",
 "ms.2a":"لِأَنَّ مِحْوَرَ التَّمَاثُلِ يُطَابِقُ نِصْفَيْهِ، فَتَنْطَبِقُ الزَّاوِيَتَانِ.",
 "ms.2b":"لِأَنَّ القَاعِدَتَيْنِ مُتَسَاوِيَتَانِ فِي الطُّولِ فِيهِ.",
 "ms.2c":"لِأَنَّ زَوَايَاهُ الأَرْبَعَ مُتَسَاوِيَةٌ كُلُّهَا مِثْلَ زَوَايَا المُسْتَطِيلِ.",
 "ms.x1":"سُدَاسِيٌّ مُحَدَّبٌ: لِمَاذَا مَجْمُوعُ زَوَايَاهُ سَبْعُمِئَةٍ وَعِشْرُونَ؟",
 "ms.x1a":"لِأَنَّ الأَقْطَارَ مِنْ رَأْسٍ وَاحِدٍ تَقْسِمُهُ أَرْبَعَةَ مُثَلَّثَاتٍ.",
 "ms.x1b":"لِأَنَّ لَهُ سِتَّةَ أَضْلَاعٍ، وَنَطْرَحُ الضِّلْعَيْنِ الأَطْوَلَيْنِ مِنْهَا.",
 "ms.x1c":"لِأَنَّ كُلَّ زَاوِيَةٍ فِي أَيِّ سُدَاسِيٍّ مُحَدَّبٍ مِئَةٌ وَعِشْرُونَ.",
 "ms.x2":"فِي شِبْهِ مُنْحَرِفٍ مُتَسَاوِي السَّاقَيْنِ: لِمَاذَا تُكَمِّلُ زَاوِيَةُ القَاعِدَةِ العُلْيَا زَاوِيَةَ السُّفْلَى عَلَى السَّاقِ نَفْسِهَا؟",
 "ms.x2a":"لِأَنَّ القَاعِدَتَيْنِ مُتَوَازِيَتَانِ وَالسَّاقَ قَاطِعٌ: هُمَا مُتَحَالِفَتَانِ.",
 "ms.x2b":"لِأَنَّ السَّاقَيْنِ مُتَسَاوِيَتَانِ، فَتَتَسَاوَى الزَّاوِيَتَانِ عَلَى السَّاقِ.",
 "ms.x2c":"لِأَنَّ مِحْوَرَ التَّمَاثُلِ يُطَابِقُ القَاعِدَةَ العُلْيَا عَلَى السُّفْلَى.",
 "ms.recall1":"نَتَذَكَّرُ: نَعُدُّ المُثَلَّثَاتِ مِنْ رَأْسٍ وَاحِدٍ، عَدَدُ الأَضْلَاعِ نَاقِصَ اثْنَيْنِ، ثُمَّ نَضْرِبُ فِي مِئَةٍ وَثَمَانِينَ.",
 "ms.recall2":"نَتَذَكَّرُ: فِي شِبْهِ المُنْحَرِفِ المُتَسَاوِي السَّاقَيْنِ تَتَسَاوَى زَاوِيَتَا كُلِّ قَاعِدَةٍ، وَالعُلْيَا تُكَمِّلُ السُّفْلَى.",
 "ms.ok":"{أَتْقَنْتَ|أَتْقَنْتِ} زَوَايَا المُضَلَّعِ وَشِبْهَ المُنْحَرِفِ!",
 "wrap.01":"المُثَلَّثُ مِفْتَاحُ كُلِّ مُضَلَّعٍ!",
 "wrap.home":["chaos","مُهِمَّةُ البَيْتِ: {اِبْحَثْ|اِبْحَثِي} عَنْ إِطَارٍ أَوْ صِينِيَّةٍ مُضَلَّعَةٍ فِي البَيْتِ، {وَعُدَّ|وَعُدِّي} أَضْلَاعَهَا، {وَاحْسُبْ|وَاحْسُبِي} مَجْمُوعَ زَوَايَاهَا، ثُمَّ {قِسْ|قِيسِي} زَاوِيَةً مَعَ {أَهْلِكَ|أَهْلِكِ}."],
}
